// Static shell caches are isolated per app-shell build. The build key comes from the
// versioned service-worker registration URL generated by pwa.js. Old generations are
// deliberately retained: a tab that has not reloaded may still be controlled by its
// previous worker and must keep access to that worker's exact CSS/JS assets.
const CACHE_PREFIX = "jularr-static-v1-";
const workerUrl = new URL(self.location.href);
const buildKey = sanitizeCacheKey(workerUrl.searchParams.get("v") || "unversioned");
const CACHE_VERSION = CACHE_PREFIX + buildKey;

const PRECACHE = [
  "/offline.html",
  "/js/offline-review.js",
  "/brand/jularr-mark.svg",
  "/icons/jularr-192.png",
  "/icons/jularr-512.png",
  "/icons/jularr-maskable-512.png",
  "/icons/apple-touch-icon.png",
  "/manifest.webmanifest"
];

self.addEventListener("install", event => {
  event.waitUntil(
    caches.open(CACHE_VERSION)
      .then(cache => cache.addAll(PRECACHE))
  );
});

// Do not call clients.claim() here. If an update is activated from one tab,
// other already-open tabs keep their current controller until they navigate or
// reload themselves. This prevents a running page from silently switching to a
// different shell generation.
self.addEventListener("activate", event => {
  event.waitUntil(Promise.resolve());
});

self.addEventListener("message", event => {
  if (event.data?.type === "SKIP_WAITING") {
    self.skipWaiting();
    return;
  }

  if (event.data?.type === "CACHE_CURRENT_ASSETS") {
    event.waitUntil(cacheCurrentAssets(event.data.urls));
  }
});

self.addEventListener("fetch", event => {
  const request = event.request;

  if (request.method !== "GET") {
    return;
  }

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) {
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request).catch(() => caches.match("/offline.html"))
    );
    return;
  }

  if (!isStaticAsset(url.pathname)) {
    return;
  }

  event.respondWith(
    isVersionedAsset(url)
      ? cacheFirstVersioned(request)
      : networkFirstStatic(request)
  );
});

// App shell only. Offline library content (manifests, chapters, assets under
// /api/client/v1/offline-library/**) is intentionally never matched here: it
// lives in IndexedDB/OPFS (wwwroot/js/offline-library-storage.js), a separate
// storage area this cache's lifecycle never touches. Do not add offline-library
// paths to this allowlist (#221).
function isStaticAsset(pathname) {
  return pathname === "/manifest.webmanifest"
    || pathname.startsWith("/css/")
    || pathname.startsWith("/js/")
    || pathname.startsWith("/build/")
    || pathname.startsWith("/fonts/")
    || pathname.startsWith("/icons/")
    || pathname.startsWith("/brand/");
}

function isVersionedAsset(url) {
  return url.searchParams.has("v")
    || url.pathname.startsWith("/build/");
}

async function cacheFirstVersioned(request) {
  const cache = await caches.open(CACHE_VERSION);
  const cached = await cache.match(request);
  if (cached) {
    return cached;
  }

  try {
    const response = await fetch(request);
    if (response.ok) {
      await cache.put(request, response.clone());
    }
    return response;
  } catch {
    return Response.error();
  }
}

async function networkFirstStatic(request) {
  const cache = await caches.open(CACHE_VERSION);

  try {
    const response = await fetch(request);
    if (response.ok) {
      await cache.put(request, response.clone());
    }
    return response;
  } catch {
    return (await cache.match(request))
      || (await cache.match(new URL(request.url).pathname))
      || Response.error();
  }
}

async function cacheCurrentAssets(urls) {
  if (!Array.isArray(urls)) {
    return;
  }

  const cache = await caches.open(CACHE_VERSION);
  const uniqueUrls = [...new Set(urls)].slice(0, 64);

  await Promise.all(uniqueUrls.map(async value => {
    try {
      const url = new URL(value, self.location.origin);
      if (url.origin !== self.location.origin
          || !isStaticAsset(url.pathname)
          || !isVersionedAsset(url)) {
        return;
      }

      const request = new Request(url.href, { cache: "reload" });
      const existing = await cache.match(request);
      if (existing) {
        return;
      }

      const response = await fetch(request);
      if (response.ok) {
        await cache.put(request, response);
      }
    } catch {
      // A failed optional refresh must never break the installed PWA.
    }
  }));
}

function sanitizeCacheKey(value) {
  return String(value)
    .trim()
    .replace(/[^a-zA-Z0-9._-]/g, "_")
    .slice(0, 160) || "unversioned";
}
